import {
  EnvironmentProviders,
  makeEnvironmentProviders,
  Provider,
} from '@angular/core';
import {
  HasStyleFactory,
  LpxCoreOptions,
  LpxStyles,
  provideLpxCore,
  withLpxCoreOptions,
} from '@volo/ngx-lepton-x.core';
import { getLpxLiteStyleProviders } from './style.provider';

export interface LpxOptions extends LpxCoreOptions, HasStyleFactory {}

export enum LpxLiteFeatureKind {
  Options,
}

export interface LpxLiteFeature<KindT extends LpxLiteFeatureKind> {
  ɵkind: KindT;
  ɵproviders: (Provider | EnvironmentProviders)[];
}

function makeLpxLiteFeature<KindT extends LpxLiteFeatureKind>(
  kind: KindT,
  providers: (Provider | EnvironmentProviders)[],
): LpxLiteFeature<KindT> {
  return {
    ɵkind: kind,
    ɵproviders: providers,
  };
}

export function withLiteOptions(
  options = {} as LpxOptions,
): LpxLiteFeature<LpxLiteFeatureKind.Options> {
  return makeLpxLiteFeature(LpxLiteFeatureKind.Options, [
    getLpxLiteStyleProviders(options.styleFactory),
    provideLpxCore(...withLpxCoreOptions(options)),
  ]);
}

export function provideLpxLite(
  ...features: LpxLiteFeature<LpxLiteFeatureKind>[]
): EnvironmentProviders {
  const providers: (Provider | EnvironmentProviders)[] = [];

  if (!features.length) {
    const defaultStyleFactory = (styles: LpxStyles) => {
      styles.push({ bundleName: 'abp-bundle' });
      return styles;
    };
    providers.push(
      getLpxLiteStyleProviders(defaultStyleFactory),
      provideLpxCore(...withLpxCoreOptions()),
    );
  }

  features.forEach(({ ɵproviders }) => providers.push(...ɵproviders));

  return makeEnvironmentProviders(providers);
}
