import { Component, Injector, ViewEncapsulation, inject } from '@angular/core';
import { NgComponentOutlet, AsyncPipe } from '@angular/common';
import { RouterLink } from '@angular/router';
import { Observable } from 'rxjs';
import {
  NgbDropdown,
  NgbDropdownToggle,
  NgbDropdownMenu,
  NgbDropdownItem,
} from '@ng-bootstrap/ng-bootstrap';
import {
  LpxNavbarItem,
  UserProfileService,
  AvatarComponent,
  LpxVisibleDirective,
} from '@volo/ngx-lepton-x.core';
import { LocalizationPipe } from '@abp/ng.core';
@Component({
  selector: 'lpx-user-profile',
  templateUrl: './user-profile.component.html',
  encapsulation: ViewEncapsulation.None,
  imports: [
    NgbDropdown,
    NgbDropdownToggle,
    AvatarComponent,
    NgbDropdownMenu,
    NgComponentOutlet,
    NgbDropdownItem,
    LpxVisibleDirective,
    RouterLink,
    AsyncPipe,
    LocalizationPipe,
  ],
})
export class UserProfileComponent {
  private service = inject(UserProfileService);
  public injector = inject(Injector);
  user$ = this.service.user$;

  onActionClick(item: LpxNavbarItem) {
    item.action?.();
  }

  isActionVisible(
    action: LpxNavbarItem,
  ): boolean | Promise<boolean> | Observable<boolean> {
    if (!action.visible) {
      return true;
    }
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    return action.visible(action, this.injector as any);
  }
}
