import { ModuleWithProviders, NgModule } from '@angular/core';
import { LpxCoreModule } from '@volo/ngx-lepton-x.core';
import { LpxOptions, provideLpxLite, withLiteOptions } from './providers';

@NgModule({
  imports: [LpxCoreModule],
})
export class LpxModule {
  /**
   * @deprecated `LpxModule.forRoot()` is deprecated. You can use `provideLpxLite` **function** instead.
   */
  static forRoot(options?: LpxOptions): ModuleWithProviders<LpxModule> {
    return {
      ngModule: LpxModule,
      providers: [provideLpxLite(withLiteOptions(options))],
    };
  }
}
